  ui_story_5030_50300003_24_dialog_content = "Bem, não posso dizer que não tenho minhas dúvidas... Mas acho que não faria mal ouvir vocês...",
  ui_story_5030_50300003_25_dialog_content = "Haha! Esse é o espírito!",
  ui_story_5030_50300003_26_dialog_content = "Acho que é hora de compartilhar essa história com nossa amiga aqui, Merylt. Você não concorda?",
  ui_story_5030_50300003_27_dialog_content = "Uh... História? Que história?",
  ui_story_5030_50300003_28_dialog_content = "Apenas um pouco de contexto, para que você aprecie totalmente o quanto nos esforçamos para ajudá-lo, é tudo!",
  ui_story_5030_50300003_29_dialog_content = "Aham! Vá em frente, Merylt! Conte-lhe a história!",
  ui_story_5030_50300003_30_dialog_content = "Ah... Ah...!",
  ui_story_5030_50300003_31_dialog_content = "Ei! Você estava bem em PlayerName apenas um segundo atrás, então por que de repente você está se calando agora?!",
  ui_story_5030_50300003_32_dialog_content = "Shhh! Deixe-a contar a história, sim?",
  ui_story_5030_50300003_33_dialog_content = "AA muito, muito tempo atrás...",
  ui_story_5030_50300003_34_dialog_content = "Em um canto distante e escondido de Astra, havia uma rainha brutal.",
  ui_story_5030_50300003_35_dialog_content = "A rainha governou este lugar por décadas, e seus súditos viveram vidas pacíficas e autossuficientes sob seu reinado.",
  ui_story_5030_50300003_36_dialog_content = "Mas quando a rainha completou sessenta anos... A máscara caiu, e sua falsa paz junto com ela.",
  ui_story_5030_50300003_37_dialog_content = "Como pode ser isso?! Não importa o que eu faça, não consigo fazer essas rugas desaparecerem!",
  ui_story_5030_50300003_38_dialog_content = "Não... eu não posso envelhecer assim...",
  ui_story_5030_50300003_39_dialog_content = "Meu povo só pode levar uma vida feliz e pacífica sob meu governo!",
  ui_story_5030_50300003_40_dialog_content = "Diga-me! O que devo fazer para prolongar minha vida e meu reinado sobre essas terras?",
  ui_story_5030_50300003_41_dialog_content = "Oh!",
  ui_story_5030_50300003_42_dialog_content = "Há uma maneira...",
  ui_story_5030_50300003_43_dialog_content = "Uma técnica proibida mencionada apenas em lendas...",
  ui_story_5030_50300003_44_dialog_content = "Ao mergulhar na força vital de meninos e meninas...",
  ui_story_5030_50300003_45_dialog_content = "E renunciando à comida em favor de sua essência preciosa e jovem...",
  ui_story_5030_50300003_46_dialog_content = "Daquele dia em diante, a vida de seus súditos mudou para sempre.",
  ui_story_5030_50300003_47_dialog_content = "As crianças começaram a desaparecer diante de seus olhos, e o caos logo desceu sobre a terra.",
  ui_story_5030_50300003_48_dialog_content = "Não havia nada que pudesse parar a loucura? Nada mesmo?",
  ui_story_5030_50300003_49_dialog_content = "A resposta logo começou a soar do fundo dos corações de todos os sobreviventes do reino...",
  ui_story_5030_50300003_50_dialog_content = "Resistir! Revolta! Somente derrubando a rainha perversa eles finalmente conheceriam a paz mais uma vez!",
  ui_story_5030_50300003_51_dialog_content = "...",
  ui_story_5030_50300003_52_dialog_content = "...",
  ui_story_5030_50300003_53_dialog_content = "E com certeza, a tirania da rainha foi finalmente interrompida pelas pessoas que ela desesperadamente procurava continuar governando.",
  ui_story_5030_50300003_54_dialog_content = "Com o tempo, os sorrisos reapareceram nos rostos das crianças, enquanto a paz e a segurança voltavam ao reino mais uma vez.",
  ui_story_5030_50300003_55_dialog_content = "Mas...",
  ui_story_5030_50300003_56_dialog_content = "Embora as ambições da rainha para a vida eterna estivessem impregnadas de violência e terror...",
  ui_story_5030_50300003_57_dialog_content = "Aqueles com mentes mais aguçadas podem aprender algo valioso com seu exemplo...",
  ui_story_5030_50300003_58_dialog_content = "A arte da extração.",
  ui_story_5030_50300003_59_dialog_content = "Das plantas, podemos extrair sua essência e criar todo tipo de temperos e ingredientes.",
  ui_story_5030_50300003_60_dialog_content = "Este é o presente que lhe oferecemos hoje.",
  ui_story_5030_50300003_61_dialog_content = "Incrível... Merylt foi realmente capaz de contar toda a história na frente de PlayerName sem perder o ritmo!",
  ui_story_5030_50300003_62_dialog_content = "Isso pede uma comemoração!",
  ui_story_5030_50300003_63_dialog_content = "Aqui! Dê uma tragada!",
  ui_story_5030_50300003_64_dialog_content = "E-Espere um minuto! Não me olhe assim! Está me assustando!",
  ui_story_5030_50300003_65_dialog_content = "Não me interpretem mal, eu sou grato pelo presente, mas eu só tenho que ter certeza...",
  ui_story_5030_50300003_66_dialog_content = "E-Essa história sobre a rainha má e o que ela fez com aquelas crianças... Não é baseada em uma história real, é?",
  ui_story_5030_50300003_66X_dialog_content = "Essa história que você está contando é muito assustadora!",
  ui_story_5030_50300003_67_dialog_content = "Quem pode dizer? Há sempre alguma verdade escondida em cada lenda, afinal...",
  ui_story_5030_50300003_68_dialog_content = "De qualquer forma, nós trouxemos seu presente, então se apresse e pegue, ok?",
  ui_story_5030_50300003_69_dialog_content = "C-Pode ser...",
  ui_story_5030_50300003_70_dialog_content = "Será que... você não gostou do nosso presente?",
  ui_story_5030_50300003_71_dialog_content = "Ah! N-Não, eu gosto!",
  ui_story_5030_50300003_72_dialog_content = "Eu só estava perguntando sobre a história, só isso!",
  ui_story_5030_50300003_73_dialog_content = "Quero dizer, foi bem assustador, afinal.",
  ui_story_5030_50300003_74_dialog_content = "Você queria que eu cheirasse, certo? Aqui vai...",
  ui_story_5030_50300003_75_dialog_content = "Espere, isso cheira incrível!",
  ui_story_5030_50300003_76_dialog_content = "Yeah, yeah!",
  ui_story_5030_50300003_77_dialog_content = "Embora, eu ainda tenho que perguntar... Que tipo de planta você usou para fazer isso?",
  ui_story_5030_50300003_78_dialog_content = "Sinto que não poderei usá-lo corretamente a menos que saiba exatamente do que é feito.",
  ui_story_5030_50300003_79_dialog_content = "As pessoas vão comer na minha cozinha, então eu tenho que levar esse tipo de coisa a sério.",
  ui_story_5030_50300003_80_dialog_content = "Ele Ele!",
  ui_story_5030_50300003_81_dialog_content = "Levei quase um dia fedorento, mas felizmente... Parece que nenhum animal foi ferido na confecção desse tempero!",
  ui_story_5030_50300003_82_dialog_content = "Fia?",
  ui_story_5030_50300003_83_dialog_content = "Você esteve nos espionando esse tempo todo, não é?",
  ui_story_5030_50300003_84_dialog_content = "O que? Como poderia ser \"espionagem\", quando este é claramente um espaço público?",
  ui_story_5030_50300003_85_dialog_content = "Eu só vim para experimentar todas as delícias em promoção. Isso é tão errado?",
  ui_story_5030_50300003_86_dialog_content = "Mas para ter certeza de que o tempero que eles te deram é realmente à base de plantas, você terá que...",
  ui_story_5030_50300003_87_dialog_content = "Você vai ter que me deixar cheirar também!",
  ui_story_5030_50300003_88_dialog_content = "Ei, imbecil! Esse é o presente de Merylt para PlayerName, então mantenha suas luvas sujas para você!",
  ui_story_5030_50300003_89_dialog_content = "*Soluçando* Mas... Mas...!",
  ui_story_5030_50300003_90_dialog_content = "(Ela está realmente derramando as lágrimas falsas sobre isso?!)",
  ui_story_5030_50300003_91_dialog_content = "Eu... eu só queria cheirar um pouco, só isso... eu nunca roubaria nem nada...",
  ui_story_5030_50300003_92_dialog_content = "Urgh... Ora, seu pirralho irritante!",
  ui_story_5030_50300003_93_dialog_content = "Está tudo bem, Subli.",
  ui_story_5030_50300003_94_dialog_content = "Vá em frente e cheire se quiser, Fia.",
  ui_story_5030_50300003_95_dialog_content = "Posso assegurar-vos que isto foi feito com plantas que recolhi meticulosamente durante um longo período de tempo.",
  ui_story_5030_50300003_96_dialog_content = "Ver? O cheiro é maravilhoso, não é?",
  ui_story_5030_50300003_97_dialog_content = "Sim você está certo!",
  ui_story_5030_50300003_98_dialog_content = "E tem uma espécie de fragrância de planta, também...",
  ui_story_5030_50300003_99_dialog_content = "Isso resolve, PlayerName! Esse tempero passa na minha avaliação profissional!",
  ui_story_5030_50300003_100_dialog_content = "Eu nunca pedi uma \"avaliação profissional\"... Você é que não deixaria passar...",
  ui_story_5030_50300003_101_dialog_content = "Eu não tenho ideia do que você está falando!",
  ui_story_5030_50300003_102_dialog_content = "De qualquer forma, obrigado, Merylt.",
  ui_story_5030_50300003_103_dialog_content = "D-Não mencione isso...!",
  ui_story_5030_50300003_104_dialog_content = "Agora vamos ver o que isso faz com o sabor do meu caldo quando eu o adiciono...",
  ui_story_5030_50300003_105_dialog_content = "Ei, que cheiro é esse?",
  ui_story_5030_50300003_106_dialog_content = "Tem um cheiro incrível!",
  ui_story_5030_50300003_107_dialog_content = "Acho que vem de lá! Vamos, vamos dar uma olhada!",
  ui_story_5030_50300004_1_dialog_content = "Número 78! Seu macarrão está pronto!",
  ui_story_5030_50300004_2_dialog_content = "Número 78! Número 78?",
  ui_story_5030_50300004_3_dialog_content = "Número 78, seu pedido é—",
  ui_story_5030_50300004_4_dialog_content = "O que é essa bagunça? Este lugar é um caos total... Não faço ideia de onde a fila começa ou termina!",
  ui_story_5030_50300004_5_dialog_content = "S-Desculpe por isso! O fim da linha é...",
  ui_story_5030_50300004_6_dialog_content = "Merda... Eu também não tenho certeza de onde está!",
  ui_story_5030_50300004_7_dialog_content = "Que tal agora? Você me diz o que deseja e eu ligo para o seu número quando seu pedido estiver pronto.",
  ui_story_5030_50300004_8_dialog_content = "Bem, quantos pedidos estão à frente dos meus?",
  ui_story_5030_50300004_9_dialog_content = "Vejamos...",
  ui_story_5030_50300004_10_dialog_content = "Bem, você seria o número 103, então... Vinte ordens, mais ou menos.",
  ui_story_5030_50300004_11_dialog_content = "Ei! Você errou meu pedido ou algo assim?",
  ui_story_5030_50300004_12_dialog_content = "Eu claramente pedi macarrão para sopa, mas você me serviu macarrão com molho de carne!",
  ui_story_5030_50300004_13_dialog_content = "M-Minhas desculpas! Deixe-me fazer-lhe outra tigela...",
  ui_story_5030_50300004_14_dialog_content = "Ei! Sem cortar a linha! Já estamos esperando aqui há tempo suficiente, como é!",
  ui_story_5030_50300004_15_dialog_content = "(Tudo está uma bagunça total agora... Isso é ruim!)",
  ui_story_5030_50300004_16_dialog_content = "(Devo parar de receber novos pedidos? Se o fizer, posso me concentrar nos clientes que já estão esperando pela comida.)",
  ui_story_5030_50300004_17_dialog_content = "Aqui está o seu macarrão.",
  ui_story_5030_50300004_18_dialog_content = "Hmph. Isso é mais parecido com isso.",
  ui_story_5030_50300004_19_dialog_content = "Seu macarrão estará pronto assim que a chaleira ferver.",
  ui_story_5030_50300004_20_dialog_content = "Pedra do Sol! Um pouco mais, se quiser?",
  ui_story_5030_50300004_21_dialog_content = "Seu pedido também está pronto. Só faltou o recheio... Pronto.",
  ui_story_5030_50300004_22_dialog_content = "Ele Ele! Sempre fica mais gostoso quando está fresco!",
  ui_story_5030_50300004_23_dialog_content = "Parece que aquela barraca está fazendo pedidos um pouco mais rápido agora.",
  ui_story_5030_50300004_24_dialog_content = "Parece assim. A fila está andando muito mais rápido também!",
  ui_story_5030_50300004_25_dialog_content = "...",
  ui_story_5030_50300004_26_dialog_content = "EU-Leona?!",
  ui_story_5030_50300004_27_dialog_content = "Por que tão surpreso? Seus olhos quase saltaram das órbitas, sabe?",
  ui_story_5030_50300004_28_dialog_content = "S-Desculpe, eu só não sabia com o que me surpreender primeiro...",
  ui_story_5030_50300004_29_dialog_content = "Vendo você visitar este lugar, ou vendo você pedir a Pedra do Sol para ferver água com seu hálito flamejante.",
  ui_story_5030_50300004_30_dialog_content = "Não importa para mim.",
  ui_story_5030_50300004_31_dialog_content = "Vi que a fila para esta barraca estava completamente fora de controle, então fiquei curioso para ver o que estava à venda.",
  ui_story_5030_50300004_32_dialog_content = "Também não esperava vê-lo aqui.",
  ui_story_5030_50300004_33_dialog_content = "Ou ver você se atrapalhando e se debatendo assim. Eu nunca vi esse seu lado antes.",
  ui_story_5030_50300004_34_dialog_content = "Ah... Hahaha...",
  ui_story_5030_50300004_35_dialog_content = "Fiquei um pouco sobrecarregado com o grande número de clientes, só isso.",
  ui_story_5030_50300004_36_dialog_content = "Entendo... Com Sunstone ajudando você a ferver água, sua eficiência deve aumentar consideravelmente.",
  ui_story_5030_50300004_37_dialog_content = "Embora... Sou só eu, ou a multidão ao redor da barraca está ficando cada vez maior?",
  ui_story_5030_50300004_38_dialog_content = "Ei você aí.",
  ui_story_5030_50300004_39_dialog_content = "A linha é assim. O que você está fazendo por aqui?",
  ui_story_5030_50300004_40_dialog_content = "Uh, Leona? Eu penso...",
  ui_story_5030_50300004_41_dialog_content = "Acho que eles estão aqui para assistir ao \"ato de cuspir fogo\" de Sunstone.",
  ui_story_5030_50300004_42_dialog_content = "O que poderia ser tão interessante sobre Sunstone cuspindo fogo? É perfeitamente normal.",
  ui_story_5030_50300004_43_dialog_content = "H-Hum...",
  ui_story_5030_50300004_44_dialog_content = "Talvez para você, mas acho que nem todos tiveram a chance de ver um dragão de verdade antes.",
  ui_story_5030_50300004_45_dialog_content = "Tá bom.",
  ui_story_5030_50300004_46_dialog_content = "Olhar! Um dragão cuspidor de fogo!",
  ui_story_5030_50300004_47_dialog_content = "Você já viu um antes?",
  ui_story_5030_50300004_48_dialog_content = "Não! Já ouvi muitas histórias sobre eles, mas esta é a primeira vez que vejo um ao vivo pessoalmente!",
  ui_story_5030_50300004_49_dialog_content = "É tão pequeno e fofo! Deve ser muito jovem, hein?",
  ui_story_5030_50300004_50_dialog_content = "Então você vende macarrão aqui?",
  ui_story_5030_50300004_51_dialog_content = "Vamos, vamos entrar na fila!",
  ui_story_5030_50300004_52_dialog_content = "Agora tem mais gente...",
  ui_story_5030_50300004_53_dialog_content = "Parece que Pedra do Sol realmente sabe como atrair uma multidão.",
  ui_story_5030_50300004_54_dialog_content = "Hum...",
  ui_story_5030_50300004_55_dialog_content = "Leona? Posso pedir um favor?",
  ui_story_5030_50300004_56_dialog_content = "Ah, se você não tem mais nada para fazer hoje...",
  ui_story_5030_50300004_57_dialog_content = "De uma vez só.",
  ui_story_5030_50300004_58_dialog_content = "Fique tranquilo, ficarei até que esteja um pouco menos ocupado.",
  ui_story_5030_50300004_59_dialog_content = "Agora agora, não fique fazendo esses olhos de cachorrinho.",
  ui_story_5030_50300004_60_dialog_content = "Vá cuidar dos negócios.",
  ui_story_5030_50300004_61_dialog_content = "Certo.",
  ui_story_5030_50300004_62_dialog_content = "Próximo cliente, por favor!",
  ui_story_5030_50300004_63_dialog_content = "Qual tipo você quer?",
  ui_story_5030_50300005_1_dialog_content = "Este é o seu pão. Olha Você aqui.",
  ui_story_5030_50300005_2_dialog_content = "Nossa, está um pouco quente direto do forno...",
  ui_story_5030_50300005_3_dialog_content = "Deixe-me embrulhar bem para você.",
  ui_story_5030_50300005_4_dialog_content = "Huh? Um cliente quer meu autógrafo? É claro!",
  ui_story_5030_50300005_5_dialog_content = "Onde você quer que eu assine?",
  ui_story_5030_50300005_6_dialog_content = "Queremos um também! Nós também!",
  ui_story_5030_50300005_7_dialog_content = "Isso não é um problema, mas posso pedir a todos um pouco de paciência? A fila é bem longa!",
  ui_story_5030_50300005_8_dialog_content = "Você quer dez? Eu vejo...",
  ui_story_5030_50300005_9_dialog_content = "Caros convidados, tenho certeza de que você já entendeu a verdadeira essência do gelo raspado.",
  ui_story_5030_50300005_10_dialog_content = "Experimentar diferentes sabores de gelo raspado não apenas ampliará seus horizontes gustativos, mas também ajudará a construir um físico saudável.",
  ui_story_5030_50300005_11_dialog_content = "Uau, é realmente delicioso...!",
  ui_story_5030_50300005_12_dialog_content = "Por que diz \"junte-se a nós\" no seu letreiro?",
  ui_story_5030_50300005_13_dialog_content = "Desde que entrei no show de gelo raspado, as caixas registradoras nunca pararam de tocar.",
  ui_story_5030_50300005_14_dialog_content = "Tornar-se um franqueado significa que você ganha tanto dinheiro quanto eu.",
  ui_story_5030_50300005_15_dialog_content = "Aprenda os truques do comércio, estimados convidados, e junte-se ao excitante mundo do gelo raspado!",
  ui_story_5030_50300005_16_dialog_content = "Parece muito bom... Vamos comprar um primeiro e provar?",
  ui_story_5030_50300005_17_dialog_content = "Sim, vamos tentar um.",
  ui_story_5030_50300005_18_dialog_content = "Aqui está o seu.",
  ui_story_5030_50300005_19_dialog_content = "E aqui está o seu!",
  ui_story_5030_50300005_20_dialog_content = "Seja um consumidor racional e reduza o desperdício! Entendi?",
  ui_story_5030_50300005_21_dialog_content = "Churrasco grelhado à mão é realmente novo!",
  ui_story_5030_50300005_22_dialog_content = "Eu! Dê-me um também, por favor!",
  ui_story_5030_50300005_23_dialog_content = "Bem, o negócio parece muito bom para todos!",
  ui_story_5030_50300005_24_dialog_content = "A seguir, este é o Rainbow com mais alguns detalhes sobre a competição!",
  ui_story_5030_50300005_25_dialog_content = "O atual proprietário de barraca mais bem classificado é o Sr. Fleur!",
  ui_story_5030_50300005_26_dialog_content = "Ha, isso não é exatamente uma surpresa. Basta olhar para a linha na frente.",
  ui_story_5030_50300005_27_dialog_content = "Em segundo lugar — o Sr. Kleken!",
  ui_story_5030_50300005_28_dialog_content = "Embora o gelo raspado seja, sem dúvida, difícil de armazenar, suas excelentes habilidades de marketing renderam a ele um ótimo resultado.",
  ui_story_5030_50300005_29_dialog_content = "Em terceiro lugar - a Sra. Smokey!",
  ui_story_5030_50300005_30_dialog_content = "Embora ela possa ser um pouco azeda, não há como negar que seu negócio tem sido excelente!",
  ui_story_5030_50300005_31_dialog_content = "Parece que todo mundo foi ao máximo, só para colocar as mãos neste Pote de Feitiço!",
  ui_story_5030_50300005_32_dialog_content = "Ops, quase esqueci nosso PlayerName!",
  ui_story_5030_50300005_33_dialog_content = "Tudo bem! Na verdade, o resultado do PlayerName também é muito bom.",
  ui_story_5030_50300005_34_dialog_content = "Embora o resultado dele não tenha deslumbrado tanto quanto os nossos três primeiros, não há dúvida de que, com um pouco de trabalho duro, a vitória é possível!",
  ui_story_5030_50300005_35_dialog_content = "Ah... Hahaha...!",
  ui_story_5030_50300005_36_dialog_content = "Bem, esse é o fim da transmissão do intervalo!",
  ui_story_5030_50300005_37_dialog_content = "Quando nos encontrarmos, será hora de anunciar os resultados da competição!",
  ui_story_5030_50300005_38_dialog_content = "Para obter esse misterioso utensílio de cozinha e realizar seus sonhos!",
  ui_story_5030_50300005_39_dialog_content = "Vamos, galera!",
  ui_story_5030_50300005_40_dialog_content = "Dê um passo à frente e participe!",
  ui_story_5030_50300005_41_dialog_content = "Ufa... Estou sentindo a pressão.",
  ui_story_5030_50300005_42_dialog_content = "Há menos clientes também, uma vez que Leona deixei.",
  ui_story_5030_50300005_43_dialog_content = "Com certeza, eles vieram até aqui para comer macarrão só para assistir aquele dragão cuspidor de fogo...",
  ui_story_5030_50300005_44_dialog_content = "Isso não parece funcionar.",
  ui_story_5030_50300005_45_dialog_content = "Você parece muito preocupado agora.",
  ui_story_5030_50300005_46_dialog_content = "Estou curioso, PlayerName, por quais problemas você está preso?",
  ui_story_5030_50300005_47_dialog_content = "Oi, Genevieve.",
  ui_story_5030_50300005_48_dialog_content = "Ah, você veio pelo macarrão?",
  ui_story_5030_50300005_49_dialog_content = "Espere. Eu tenho. Você está procurando por alguém, certo?",
  ui_story_5030_50300005_50_dialog_content = "Pois aí está ela...",
  ui_story_5030_50300005_51_dialog_content = "Ei, espere! Espere um segundo!",
  ui_story_5030_50300005_52_dialog_content = "O que você está pensando, pobre PlayerName?",
  ui_story_5030_50300005_53_dialog_content = "Estou aqui apenas para ajudá-lo.",
  ui_story_5030_50300005_54_dialog_content = "Ajude-me?",
  ui_story_5030_50300005_55_dialog_content = "Ah, eu me lembro agora. Você também não é muito habilidoso com fogo...?",
  ui_story_5030_50300005_56_dialog_content = "Ajudá-lo a ferver a água mais rápido, depois enxaguar e repetir?",
  ui_story_5030_50300005_57_dialog_content = "Mesmo assim, isso é apenas uma repetição dos resultados recentes, não uma grande melhoria.",
  ui_story_5030_50300005_58_dialog_content = "Você, você deve olhar para a foto maior.",
  ui_story_5030_50300005_59_dialog_content = "As pessoas vêm aqui para algo novo e fresco, certo?",
  ui_story_5030_50300005_60_dialog_content = "Pense nisso.",
  ui_story_5030_50300005_61_dialog_content = "Imagine se sua barraca não oferecesse apenas sustento, mas também fornecesse alguns extras para clientes cansados?",
  ui_story_5030_50300005_62_dialog_content = "O que você quer dizer com \"extras\"?",
  ui_story_5030_50300005_63_dialog_content = "U-Um, Genevieve, estamos no relvado de Lumopolis. Este não é o território da Verdadeira Ordem ou da Umbraton.",
  ui_story_5030_50300005_64_dialog_content = "Não seremos presos se formos longe demais?",
  ui_story_5030_50300005_65_dialog_content = "Sobre o que?",
  ui_story_5030_50300005_66_dialog_content = "Por \"extras\", quero dizer melhores serviços ao cliente, como espera e massagens!",
  ui_story_5030_50300005_67_dialog_content = "Oh, esses tipos de serviços!",
  ui_story_5030_50300005_68_dialog_content = "Eu pensei que você queria que eu jogasse um pouco de gim ou algo assim!",
  ui_story_5030_50300005_69_dialog_content = "Vamos esperar até a noite para esse tipo de coisa!",
  ui_story_5030_50300005_70_dialog_content = "Está muito quente lá fora para beber agora, e impossível saborear a delícia do gin.",
  ui_story_5030_50300005_71_dialog_content = "Tudo bem, obrigado pela sua sugestão, Genevieve...",
  ui_story_5030_50300005_72_dialog_content = "M-Mas, a coisa é, eu realmente não tenho mãos livres para oferecer esses serviços?",
  ui_story_5030_50300005_73_dialog_content = "Não precisa de suas mãos.",
  ui_story_5030_50300005_74_dialog_content = "Já tenho muitos \"lacaios\" dando as mãos...",
  ui_story_5030_50300005_75_dialog_content = "Senhora Genevieve! Senhora Genevieve!!",
  ui_story_5030_50300006_1_dialog_content = "(Deve estar realmente assando agora.)",
  ui_story_5030_50300006_2_dialog_content = "(Eu apenas senti o suor escorrer do meu queixo...)",
  ui_story_5030_50300006_3_dialog_content = "(Se eu ouvir com atenção, provavelmente poderia ouvir aquela gota de suor cair no chão.)",
  ui_story_5030_50300006_4_dialog_content = "(Pelo menos ainda há uma brisa, mesmo em um dia tão quente...)",
  ui_story_5030_50300006_5_dialog_content = "(Não consigo sentir o alívio frio que o vento traz... ou até mesmo sentir o próprio vento.)",
  ui_story_5030_50300006_6_dialog_content = "(Eh... Então como eu sei que está mesmo soprando?)",
  ui_story_5030_50300006_7_dialog_content = "(Bem, devem ter sido aquelas três folhas flutuando no ar na minha frente.)",
  ui_story_5030_50300006_8_dialog_content = "(Três folhas... Manchas de água no chão. E um prato que alguém quebrou acidentalmente... Eh?)",
  ui_story_5030_50300006_9_dialog_content = "(Um par de sapatos apareceu no chão. Os dedos pontudos deles param na minha frente...)",
  ui_story_5030_50300006_10_dialog_content = "Espere... Dedos pontudos, parando na frente da minha barraca de ramen?",
  ui_story_5030_50300006_11_dialog_content = "Então, isso significa...",
  ui_story_5030_50300006_12_dialog_content = "Um convidado! Um convidado há muito esperado!",
  ui_story_5030_50300006_13_dialog_content = "Caro hóspede, por favor, dê uma olhada! Confira nosso macarrão!",
  ui_story_5030_50300006_14_dialog_content = "O negócio não parece muito animado.",
  ui_story_5030_50300006_15_dialog_content = "É... Jeno?",
  ui_story_5030_50300006_16_dialog_content = "Você está aqui para o macarrão?",
  ui_story_5030_50300006_17_dialog_content = "Ou você está fazendo as rondas como anfitrião...?",
  ui_story_5030_50300006_18_dialog_content = "Estou aqui pelo macarrão.",
  ui_story_5030_50300006_19_dialog_content = "... Oh! Eu vejo.",
  ui_story_5030_50300006_20_dialog_content = "E que tipo de macarrão você está procurando?",
  ui_story_5030_50300006_21_dialog_content = "Não há muitas pessoas aqui agora, então eu poderia deixar você experimentar todas elas...",
  ui_story_5030_50300006_22_dialog_content = "Uma tigela de sopa de macarrão está bem.",
  ui_story_5030_50300006_23_dialog_content = "Obrigado.",
  ui_story_5030_50300006_24_dialog_content = "É claro! Chegando direto...",
  ui_story_5030_50300006_25_dialog_content = "Então, o que você acha? Isso é bom?",
  ui_story_5030_50300006_26_dialog_content = "Muito delicioso.",
  ui_story_5030_50300006_27_dialog_content = "Fico feliz em ouvir isso.",
  ui_story_5030_50300006_28_dialog_content = "Então, não consigo entender por que seu negócio está tão lento agora.",
  ui_story_5030_50300006_29_dialog_content = "Certamente deveria haver mais demanda para esse tipo de coisa, certo?",
  ui_story_5030_50300006_30_dialog_content = "Para ser honesto, os negócios não estavam tão ruins agora...",
  ui_story_5030_50300006_31_dialog_content = "É que os convidados pareciam mais atraídos pelos extras.",
  ui_story_5030_50300006_32_dialog_content = "Extras?",
  ui_story_5030_50300006_33_dialog_content = "Hmm... Talvez seja melhor dizer truques para angariar negócios.",
  ui_story_5030_50300006_34_dialog_content = "Como o dragão cuspidor de fogo ou melhores serviços ao cliente. Coisas assim.",
  ui_story_5030_50300006_35_dialog_content = "Bem, o macarrão tem um gosto diferente?",
  ui_story_5030_50300006_36_dialog_content = "Quase o mesmo, eu acho. Seu ramen e os vendidos anteriormente foram feitos exatamente da mesma maneira.",
  ui_story_5030_50300006_37_dialog_content = "Você deve ter tido muitos clientes, certo?",
  ui_story_5030_50300006_38_dialog_content = "Sim. Definitivamente havia uma longa fila.",
  ui_story_5030_50300006_39_dialog_content = "Você deve estar ansioso para servir macarrão a cada cliente ainda mais rápido naquela época, suponho.",
  ui_story_5030_50300006_40_dialog_content = "Bem, isso também é um fato...",
  ui_story_5030_50300006_41_dialog_content = "Hmm... Acho que entendi o que você está tentando dizer.",
  ui_story_5030_50300006_42_dialog_content = "Porque eu estava com tanta pressa, era difícil evitar erros.",
  ui_story_5030_50300006_43_dialog_content = "E por causa disso, não há chance de fazer essas porções no mesmo padrão que você acabou de comer.",
  ui_story_5030_50300006_44_dialog_content = "Não... quero dizer, acho que você deveria se concentrar mais na comida em si.",
  ui_story_5030_50300006_45_dialog_content = "O estresse de lidar com longas filas é apenas um problema.",
  ui_story_5030_50300006_46_dialog_content = "Mas a linha inferior é que você simplesmente não consegue servir tantas pessoas.",
  ui_story_5030_50300006_47_dialog_content = "Talvez. Mas eles não têm paciência para esperar muito.",
  ui_story_5030_50300006_48_dialog_content = "Que tal avisá-los do tempo de espera aproximado?",
  ui_story_5030_50300006_49_dialog_content = "Os clientes atraídos pelos extras ficariam ainda mais impacientes.",
  ui_story_5030_50300006_50_dialog_content = "Acho um paradoxo...",
  ui_story_5030_50300006_51_dialog_content = "Você vê, a questão toda é que eu quero colocar minhas mãos nesse pote. E para que isso aconteça, quanto mais vendas melhor.",
  ui_story_5030_50300006_52_dialog_content = "Então você acha que os extras são apenas algo que você tem que fazer.",
  ui_story_5030_50300006_53_dialog_content = "Mas você pode garantir que todas as pessoas atraídas pelos extras realmente compram seu macarrão?",
  ui_story_5030_50300006_54_dialog_content = "...",
  ui_story_5030_50300006_55_dialog_content = "Bem, eu... Não.",
  ui_story_5030_50300006_56_dialog_content = "É que eu fico ainda mais nervosa quando vejo tanta gente esperando.",
  ui_story_5030_50300006_57_dialog_content = "E um pouco ansioso.",
  ui_story_5030_50300006_58_dialog_content = "Só consigo pensar em fazer uma tigela, e depois a próxima, e a seguinte...",
  ui_story_5030_50300006_59_dialog_content = "Eu realmente quis dizer isso quando disse que esta tigela de macarrão diante de mim estava deliciosa.",
  ui_story_5030_50300006_60_dialog_content = "Não ouso dizer: \"cabeças frias produzem macarrão quente\".",
  ui_story_5030_50300006_61_dialog_content = "Ou \"Concentre-se na comida, esqueça o mundo\", esses slogans banais.",
  ui_story_5030_50300006_62_dialog_content = "Bem, tudo o que quero dizer é: esta tigela de macarrão é deliciosa.",
  ui_story_5030_50300006_63_dialog_content = "Se eu souber que alguém pretende abrir um restaurante no futuro, indicarei sua direção para obter dicas sobre como fazer macarrão.",
  ui_story_5030_50300006_64_dialog_content = "Hum...",
  ui_story_5030_50300006_65_dialog_content = "Obrigado, Jeno.",
  ui_story_5030_50300006_66_dialog_content = "Foi isso que você pensou quando começou a se apresentar?",
  ui_story_5030_50300006_67_dialog_content = "Você sabe, não preste atenção ao tamanho do público, mas apenas concentre-se na magia?",
  ui_story_5030_50300006_68_dialog_content = "De uma vez só.",
  ui_story_5030_50300006_69_dialog_content = "Magia é minha vida. Eu não me importo com mais nada.",
  ui_story_5030_50300006_70_dialog_content = "Eu tenho que dizer, esse tipo de atitude é demais.",
  ui_story_5030_50300006_71_dialog_content = "Você tem mais alguns convidados.",
  ui_story_5030_50300006_72_dialog_content = "Se você me der licença. Aguardo seus milagres.",
  ui_story_5030_50300006_73_dialog_content = "Foco na comida em si...?",
  ui_story_5030_50300006_74_dialog_content = "O macarrão estava ótimo. Tome estes ingredientes como um agradecimento!",
  ui_story_5030_50300006_75_dialog_content = "Posso assegurar-vos que isto foi feito com plantas que recolhi meticulosamente durante um longo período de tempo.",
  ui_story_5030_50300006_76_dialog_content = "Ver? O cheiro é maravilhoso, não é?",
  ui_story_5030_50300006_77_dialog_content = "Este livro de receitas secreto é para você!",
  ui_story_5030_50300006_78_dialog_content = "Você certamente não vai nos decepcionar, vai, PlayerName?",
  ui_story_5030_50300006_79_dialog_content = "Ah! Entendo!",
  ui_story_5030_50300007_1_dialog_content = "Você ouviu? Essa lenda absoluta também vai participar!",
  ui_story_5030_50300007_2_dialog_content = "Tio Johnny? Quer dizer que o tio Johnny vem aqui pessoalmente?!",
  ui_story_5030_50300007_3_dialog_content = "Não, não... Acho que o nome dele era algo como Noodle God.",
  ui_story_5030_50300007_4_dialog_content = "Meu amigo foi experimentar a barraca do Noodle God. Veredicto: ele nunca comeu macarrão tão delicioso em toda a sua vida!",
  ui_story_5030_50300007_5_dialog_content = "Sério? Isso soa divino. Acho que também quero experimentar.",
  ui_story_5030_50300007_6_dialog_content = "Veja, bem ali—",
  ui_story_5030_50300007_7_dialog_content = "203! Este sou eu! Pedido número 203!",
  ui_story_5030_50300007_8_dialog_content = "Você foi enganado, amigo. Acho que você vai descobrir que eu tenho 203 anos.",
  ui_story_5030_50300007_9_dialog_content = "Vendo que os 203s estão lutando, por que não dá para mim? Eu sou 204!",
  ui_story_5030_50300007_10_dialog_content = "Uau... Muitas pessoas na fila...?",
  ui_story_5030_50300007_11_dialog_content = "(Meus braços doem...)",
  ui_story_5030_50300007_12_dialog_content = "(Eu nem tenho certeza se posso fazer algo tão básico quanto entregar as tigelas...)",
  ui_story_5030_50300007_13_dialog_content = "(Mas se não fosse por isso...)",
  ui_story_5030_50300007_14_dialog_content = "(Para o meu sonho final!)",
  ui_story_5030_50300007_15_dialog_content = "(Para permitir que todos em Cloud Gardens e Colossus desfrutem de macarrão delicioso e conveniente!)",
  ui_story_5030_50300007_16_dialog_content = "-Ei! 204! Sua vez!",
  ui_story_5030_50300007_17_dialog_content = "Uau! Parece que está zumbindo por aqui, PlayerName!",
  ui_story_5030_50300007_18_dialog_content = "Uh, você está aqui para o macarrão também, Rainbow?",
  ui_story_5030_50300007_19_dialog_content = "Não dessa vez. Estou aqui para fazer um anúncio da competição!",
  ui_story_5030_50300007_20_dialog_content = "PARABÉNS, PlayerName!",
  ui_story_5030_50300007_21_dialog_content = "Parabenizando-me?",
  ui_story_5030_50300007_22_dialog_content = "Você está me dizendo que eu consegui...",
  ui_story_5030_50300007_23_dialog_content = "Agora você está em segundo lugar!",
  ui_story_5030_50300007_24_dialog_content = "... Por que exatamente você está me parabenizando então?",
  ui_story_5030_50300007_25_dialog_content = "Huh? Você foi quarto no final da última rodada!",
  ui_story_5030_50300007_26_dialog_content = "Isso é algum progresso digno de parabéns, se alguma vez houve algum!",
  ui_story_5030_50300007_27_dialog_content = "Bem, se você insiste em colocar assim...",
  ui_story_5030_50300007_28_dialog_content = "Quem está em primeiro lugar?",
  ui_story_5030_50300007_29_dialog_content = "Apenas o fundador do império do pão – o Sr. Fleur!",
  ui_story_5030_50300007_30_dialog_content = "Estamos na última meia hora da competição. O trabalho duro pode ajudar o PlayerName a ultrapassar a linha?",
  ui_story_5030_50300007_31_dialog_content = "Certamente vou tentar.",
  ui_story_5030_50300007_32_dialog_content = "Isso está pronto? Já estou acordado? Eu sou 205!",
  ui_story_5030_50300007_33_dialog_content = "Um segundo, quase pronto!",
  ui_story_5030_50300007_34_dialog_content = "Incrível! Mesmo conversando com o anfitrião, suas mãos nunca pararam!",
  ui_story_5030_50300007_35_dialog_content = "Este é o talento secreto do Deus Noodle?",
  ui_story_5030_50300007_36_dialog_content = "Deus do Macarrão?",
  ui_story_5030_50300007_37_dialog_content = "Por que, olá!",
  ui_story_5030_50300007_38_dialog_content = "Posso perguntar quem você quis dizer com \"Noodle God\"?",
  ui_story_5030_50300007_39_dialog_content = "Uh, apenas o dono desta barraca de macarrão.",
  ui_story_5030_50300007_40_dialog_content = "Uau - agora ISSO é uma longa fila!",
  ui_story_5030_50300007_41_dialog_content = "É só porque o macarrão dele é muito gostoso.",
  ui_story_5030_50300007_42_dialog_content = "Deus do Macarrão? Pff...",
  ui_story_5030_50300007_43_dialog_content = "Claramente, apenas Anzu e Momo são dignos de tal epíteto!",
  ui_story_5030_50300007_44_dialog_content = "Acho melhor dar uma olhada nesse cara, ver o quão habilidoso ele é!",
  ui_story_5030_50300007_45_dialog_content = "Próximo! Olá! Qual sabor você gostaria—",
  ui_story_5030_50300007_46_dialog_content = "... Yao?!",
  ui_story_5030_50300007_47_dialog_content = "Uau agora! Poxa...!",
  ui_story_5030_50300007_48_dialog_content = "Espere um minuto... Você está me dizendo que VOCÊ é o Deus do Macarrão de quem eles estavam falando?",
  ui_story_5030_50300007_49_dialog_content = "Bem, escute, eu posso ser aquele que todo mundo está chamando assim, mas... Não é como se eu me promovesse dessa maneira!",
  ui_story_5030_50300007_50_dialog_content = "Então é mesmo a sua cozinha que impressiona a todos?",
  ui_story_5030_50300007_51_dialog_content = "Quero dizer, sim? Provavelmente...",
  ui_story_5030_50300007_52_dialog_content = "Vir para cá fez parte das suas viagens?",
  ui_story_5030_50300007_53_dialog_content = "Sim! Eu queria dar uma olhada ao redor!",
  ui_story_5030_50300007_54_dialog_content = "Mas devo dizer que é uma visão um tanto estranha - você, sozinho, cozinhando macarrão!",
  ui_story_5030_50300007_55_dialog_content = "Ahhh! Então é para aquele pote de feitiçaria, hein? Não é à toa que acabei de ver Kleken bem ali...",
  ui_story_5030_50300007_56_dialog_content = "Uau, que motivação inesperadamente nobre para vencer, PlayerName!",
  ui_story_5030_50300007_57_dialog_content = "Woo... Boo-hoo... Eu sinto você. Não diga mais nada, PlayerName!",
  ui_story_5030_50300007_58_dialog_content = "Deve haver pelo menos 20 pessoas atrás de mim. Quantos pedidos mais você pode fazer?",
  ui_story_5030_50300007_59_dialog_content = "Hmm... você poderia gerenciar 87?",
  ui_story_5030_50300007_60_dialog_content = "Fique tranquilo, essas 87 tigelas—",
  ui_story_5030_50300007_61_dialog_content = "JÁ ESTÃO TODOS CONTRATADOS POR MIM!",
  ui_story_5030_50300007_62_dialog_content = "Quem é o fornecedor do macarrão e das coberturas?",
  ui_story_5030_50300007_63_dialog_content = "Deixe-me comprar todos os ingredientes crus também!",
  ui_story_5030_50300007_64_dialog_content = "Yao, ouça, eu...",
  ui_story_5030_50300007_65_dialog_content = "Eh, não precisa me agradecer!",
  ui_story_5030_50300007_66_dialog_content = "Para um sonho tão grande... eu simplesmente devo dar uma mão!",
  ui_story_5030_50300007_67_dialog_content = "Além disso, eu sou fenomenalmente rico, haha!",
  ui_story_5030_50300007_68_dialog_content = "A contagem regressiva final começa—!",
  ui_story_5030_50300007_69_dialog_content = "Uau, cada concorrente está intensificando!",
  ui_story_5030_50300007_70_dialog_content = "Neste momento incrivelmente tenso – TRÊS!",
  ui_story_5030_50300007_71_dialog_content = "Detalhes de contato por escrito de Kleken para investimento em seu próprio tentáculo!",
  ui_story_5030_50300007_72_dialog_content = "Esta é uma espera de roer as unhas pelos resultados – DOIS!",
  ui_story_5030_50300007_73_dialog_content = "Fleur mais uma vez mostrou aquele sorriso vencedor de marca registrada para seus fãs!",
  ui_story_5030_50300007_74_dialog_content = "A empolgação é quase demais para aguentar – UM!",
  ui_story_5030_50300007_75_dialog_content = "Declaro que o campeão desta batalha pelo Pote de Feitiçaria é—",
  ui_story_5030_50300007_76_dialog_content = "PlayerName!",
  ui_story_5030_50300007_77_dialog_content = "PlayerName, que vendeu uma quantidade incrível de macarrão, tudo em busca de seu grande sonho!",
  ui_story_5030_50300007_78_dialog_content = "Vamos parabenizar o PlayerName por ganhar este misterioso e intrigante pote de feitiçaria!",
  ui_story_5030_50300007_79_dialog_content = "Parabéns, PlayerName.",
  ui_story_5030_50300007_80_dialog_content = "Então PlayerName ganhou!",
  ui_story_5030_50300007_81_dialog_content = "Você sabe como usá-lo?",
  ui_story_5030_50300007_82_dialog_content = "Err... Obrigado a todos.",
  ui_story_5030_50300007_83_dialog_content = "Eu acho que preciso gastar tempo explorando como usá-lo.",
  ui_story_5030_50300007_84_dialog_content = "Acho que já vi esse tipo de utensílio de cozinha antes, mas essa panela...",
  ui_story_5030_50300007_85_dialog_content = "Uh, você não sabe como usá-lo, não é?",
  ui_story_5030_50300007_86_dialog_content = "Eu, eu só preciso refrescar minha memória!",
  ui_story_5030_50300007_87_dialog_content = "(Como exatamente eu ativo o cozimento automático?)",
  ui_story_5030_50300007_88_dialog_content = "(Eu pareceria um pouco estúpido se tentasse sentir?)",
  ui_story_5030_50300007_89_dialog_content = "Posso dar uma olhada?",
  ui_story_5030_50300007_90_dialog_content = "De nada.",
  ui_story_5030_50300007_91_dialog_content = "Eu não faço ideia. Isso é totalmente diferente de qualquer outro utensílio de cozinha que eu já vi...",
  ui_story_5030_50300007_92_dialog_content = "Hum... Mas sua estrutura requintada realmente dá vontade de saber como funciona.",
  ui_story_5030_50300007_93_dialog_content = "PlayerName, quando você alcançar seu sonho, poderia me emprestar este utensílio de cozinha por alguns dias?",
  ui_story_5030_50300007_94_dialog_content = "Sem problemas! Eu só tenho que descobrir como a coisa funciona, primeiro...",
  ui_story_5030_50300007_95_dialog_content = "Acho que precisa de algum tipo de empurrão externo para continuar.",
  ui_story_5030_50300007_96_dialog_content = "Incêndio? Precisa de fogo?",
  ui_story_5030_50300007_97_dialog_content = "Não custa tentar?",
  ui_story_5030_50300007_98_dialog_content = "... Isso vai longe demais, não é?!",
  ui_story_5030_50300007_99_dialog_content = "Mas veja, não há nenhum dano.",
  ui_story_5030_50300007_100_dialog_content = "Que tal... tentar um pouco de água?",
  ui_story_5030_50300007_101_dialog_content = "...",
  ui_story_5030_50300007_102_dialog_content = "Queime com as ondas do mar!",
  ui_story_5030_50300007_103_dialog_content = "Fica parado.",
  ui_story_5030_50300007_104_dialog_content = "Er, talvez precise de algum tipo de força mais suave e controlada?",
  ui_story_5030_50300007_105_dialog_content = "Estou aqui!",
  ui_story_5030_50300007_106_dialog_content = "Parece duro como uma rocha.",
  ui_story_5030_50300007_107_dialog_content = "Ce-ce...",
  ui_story_5030_50300007_108_dialog_content = "Você não pode usar o pensamento moderno para entender esses tipos de coisas antigas das ruínas...",
  ui_story_5030_50300007_109_dialog_content = "Mas como saberemos se não tentarmos?",
  ui_story_5030_50300007_110_dialog_content = "Bem... Tentar atacar com Lumina?",
  ui_story_5030_50300007_111_dialog_content = "E-eu...",
  ui_story_5030_50300007_112_dialog_content = "Com certeza, sem dados...",
  ui_story_5030_50300007_113_dialog_content = "O tio Johnny realmente usou essa panela uma vez?",
